INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(29501, '1 John 5:10', '1 John', 5, 10, '&nbsp;هر څوک چې د خُدائ پاک په زوئ ايمان ساتى نو په خپلو زړونو کښې دا ګواهى ورکوى. خو هغوئ څوک چې په دې خبره ايمان نۀ ساتى هغوئ خُدائ پاک دروغژن ګڼى ځکه چې هغوئ د خُدائ پاک هغه ګواهى نۀ منى کومه ګواهى چې هغۀ د خپل زوئ په حقله کړې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29502, '1 John 5:11', '1 John', 5, 11, '&nbsp;او هغه ګواهى دا ده چې خُدائ پاک مونږ له د تل ژوندون راکړے دے او دا ژوندون د هغۀ په زوئ کښې دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29503, '1 John 5:12', '1 John', 5, 12, '&nbsp;هر چا سره چې زوئ وى هغۀ سره ژوندون هم وى، او هر چا سره چې د خُدائ پاک زوئ نۀ وى هغۀ سره ژوندون نۀ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29504, '1 John 5:13', '1 John', 5, 13, '&nbsp;زۀ دا څيزونه تاسو ته ليکم د چا چې د خُدائ پاک د زوئ په نامه ايمان دے، نو چې تاسو په دې پوهه شئ چې تاسو د تل عُمرى ژوندون خاوندان يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29505, '1 John 5:14', '1 John', 5, 14, '&nbsp;او په دې زمونږ باور دے چې کۀ مونږ د هغۀ د مرضۍ په مطابق د هغۀ نه څۀ وغواړو نو هغه زمونږ سوالونه اورى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29506, '1 John 5:15', '1 John', 5, 15, '&nbsp;او کۀ مونږ په دې پوهه شو چې خُدائ پاک زمونږ خواست اورى نو دا راته هم پته ده چې څۀ هم ترې غوښتى دى هغه مونږ ته مِلاو شوى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29507, '1 John 5:16', '1 John', 5, 16, '&nbsp;کۀ تاسو خپل ورور يا خور په داسې ګناه کولو ووينئ چې اَنجام يې مرګ نۀ وى، نو د هغوئ دپاره د خُدائ پاک نه دُعا وغواړئ او هغه به ورله ژوندون ورکړى. خو داسې ګناه هم شته چې اَنجام يې مرګ وى او زۀ دا نۀ وايم چې تاسو دې د هغوئ په حقله دُعا وغواړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29508, '1 John 5:17', '1 John', 5, 17, '&nbsp;ټول بد کارونه ګناه ده خو داسې ګناه هم شته چې اَنجام يې مرګ نۀ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29509, '1 John 5:18', '1 John', 5, 18, '&nbsp;مونږ ته پته ده چې څوک چې د خُدائ روحانى بچى دى هغوئ په ګناه کښې نۀ اوسيږى، خو هغه څوک چې د خُدائ پاک روحانى بچى دى هغه په خپله د هغوئ حفاظت کوى او اِبليس هغوئ ته ورنزدې کېدے نۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29510, '1 John 5:19', '1 John', 5, 19, '&nbsp;مونږ په دې پوهه يُو چې مونږ د خُدائ پاک بچى يُو، او ټوله دُنيا د شرير په قبضه کښې پرته ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29511, '1 John 5:20', '1 John', 5, 20, '&nbsp;او مونږ ته پته ده چې د خُدائ زوئ راغلے دے او مونږ ته يې دا پوهه راکړه چې مونږ هغه وپېژنو څوک چې رښتينے دے، او مونږ په هغۀ کښې يُو څوک چې رښتينے دے يعنې د هغۀ زوئ عيسىٰ مسيح. هغه رښتينے خُدائ پاک او د تل ژوندون دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29512, '1 John 5:21', '1 John', 5, 21, '&nbsp;زما ګرانو بچو، د بُتانو نه ځان وساتئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29513, '2 John 1:1', '2 John', 1, 1, '&nbsp;دا خط د مشر د طرفه هغه منتخب شوې ښځې او د هغې بچو ته دے، چا سره چې زما په رښتيا مينه ده، يواځې زۀ نه، بلکې د هغه ټولو څوک چې د حق نه خبر دى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29514, '2 John 1:2', '2 John', 1, 2, '&nbsp;د هغه حق د خاطره چې په مونږ کښې اوسيږى او تل تر تله به مونږ سره وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29515, '2 John 1:3', '2 John', 1, 3, '&nbsp;د خُدائ پلار او د هغۀ د زوئ عيسىٰ مسيح فضل، رحم او سلامتى به په حقيقت او مينې سره په مونږ کښې وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29516, '2 John 1:4', '2 John', 1, 4, '&nbsp;زۀ په دې ډېر خوشحاله شوم چې مې واورېدل چې ستاسو څۀ بچى د حق په لار روان دى لکه څنګه چې د پلار نه مونږ ته حُکم شوے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29517, '2 John 1:5', '2 John', 1, 5, '&nbsp;اے ګرانې محترمې، زۀ اوس ستا نه تپوس کوم داسې نه چې زۀ درته يو نوے حُکم ليکم، بلکې کوم چې مونږ ته د شروع نه راکړے شوے دے چې مونږ دې د يو بل سره مينه کوُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29518, '2 John 1:6', '2 John', 1, 6, '&nbsp;او دا مينه ده چې مونږ د هغۀ د حُکمونو په مطابق ژوند وکړُو. د هغۀ حُکم دا دے کوم چې تاسو د اول نه اورېدلے دے، نو چې تاسو د هغې په نقش قدم تلل وکړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29519, '2 John 1:7', '2 John', 1, 7, '&nbsp;ځکه چې ډېر دوکه بازان دُنيا کښې خوارۀ شوى دى څوک چې د عيسىٰ مسيح په جسم کښې راتلل نۀ منى، داسې کسان لوئ ټګماران او خردجالان دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29520, '2 John 1:8', '2 John', 1, 8, '&nbsp;خبردار اوسئ چې زمونږ هغه خوارى ضائع لاړه نۀ شى کومه چې مونږ په تاسو کړې ده بلکې دا چې تاسو د هغې پوره اجر حاصل کړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29521, '2 John 1:9', '2 John', 1, 9, '&nbsp;څوک هم چې بې‌لارې شى او د مسيح د تعليم په مطابق ژوند نۀ تېروى، خُدائ پاک د هغۀ سره نشته. خو هر څوک چې د مسيح د تعليم په مطابق ژوند تېروى نو د هغۀ سره پلار او زوئ دواړه شته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29522, '2 John 1:10', '2 John', 1, 10, '&nbsp;کۀ څوک درته راشى او دا تعليم درنۀ کړى نو هغه خپل کور ته مۀ پرېږدئ او مۀ ورته هرکلے وايئ،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29523, '2 John 1:11', '2 John', 1, 11, '&nbsp;ځکه چې هر څوک چې هغۀ ته هرکلے وائى، د هغۀ په بدو کارونو کښې شريک دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29524, '2 John 1:12', '2 John', 1, 12, '&nbsp;اګر کۀ ډيرې خبرې داسې دى چې زۀ يې تاسو ته ليکل غواړم خو د هغې زۀ په ليک کښې راوستل نۀ غواړم، خو د دې په ځائ زۀ دا اُميد کوم چې در به شم او درسره به په مخامخ خبرې وکړم نو چې زمونږ خوشحالى پوره شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29525, '2 John 1:13', '2 John', 1, 13, '&nbsp;ستا هغه خور چې خُدائ پاک غوره کړې ده د هغې بچى تا ته سلام کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29526, '3 John 1:1', '3 John', 1, 1, '&nbsp;د مشر د طرف نه، خوږ ګايوس ته، د چا سره چې زۀ د زړۀ نه مينه کوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29527, '3 John 1:2', '3 John', 1, 2, '&nbsp;زما خوږه ګايوسه، زۀ دُعا غواړم چې تۀ دې داسې روغ جوړ اوسې لکه څنګه چې په روحانى توګه روغ جوړ يې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29528, '3 John 1:3', '3 John', 1, 3, '&nbsp;کله چې وروڼه راغلل او ما ته يې دا ګواهى راکړه چې تۀ څومره رښتينے ژوند تېروې نو په دې ډېر خوشحاله شوم او چې تۀ څومره په رښتينې لار روان يې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29529, '3 John 1:4', '3 John', 1, 4, '&nbsp;د دې نه زياته خوشحالى ما ته په بل هيڅ څيز کښې نشته چې کله زۀ دا واورم چې زما بچى په حقه لار روان دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29530, '3 John 1:5', '3 John', 1, 5, '&nbsp;اے ګرانه وروره، تۀ د وروڼو په خِدمت کښې ډېر وفادار يې، اګر کۀ تا ته هغوئ پردى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29531, '3 John 1:6', '3 John', 1, 6, '&nbsp;هغوئ دلته د جماعت په وړاندې ستا د ښۀ ورورولۍ ګواهى ورکړه. نو دا به ستا مهربانى وى چې د دوئ په سفر کښې هم هغه شان مدد جارى وساتى د کومې ورورولۍ نه چې خُدائ پاک رضا وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29532, '3 John 1:7', '3 John', 1, 7, '&nbsp;هغوئ د عيسىٰ د نوم د خِدمت کولو دپاره په سفر ووتل او د بې‌دينو نه يې هيڅ قسمه مدد حاصل نۀ کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29533, '3 John 1:8', '3 John', 1, 8, '&nbsp;نو په دې وجه په مونږ لازم دى چې د داسې خلقو مدد وکړُو نو چې مونږ د حقيقت په خورولو کښې د هغوئ ملګرى شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29534, '3 John 1:9', '3 John', 1, 9, '&nbsp;ما جماعت ته څۀ وليکل خو ديوترفيس چې د مشرۍ شوق لرونکے دے هغه زمونږ اختيار نۀ منى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29535, '3 John 1:10', '3 John', 1, 10, '&nbsp;نو کۀ زۀ درغلم نو هغه کارونه به درته په ګوته کړم کوم چې هغه کوى او زمونږ خلاف فضول او بدې خبرې کوى، او لا په دې هم نۀ صبريږى بلکې زمونږ وروڼو ته د هر کلى وئيلو نه هم اِنکار کوى او څوک چې داسې کوى هغوئ هم منع کوى تر دې چې د جماعت نه يې هم شړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29536, '3 John 1:11', '3 John', 1, 11, '&nbsp;زما خوږه ملګريه، د بدۍ پيروى مۀ کوه بلکې ښۀ کوه، ښۀ کار کوونکى د خُدائ پاک بچى دى او څوک چې بد کارونه کوى هغوئ خُدائ ليدلے نۀ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29537, '3 John 1:12', '3 John', 1, 12, '&nbsp;د ديميتريوس دپاره هر څوک ښۀ ګواهى ورکوى او دا حقيقت هم دے، مونږ پخپله هم د هغۀ ګواهى ورکوو او تۀ خبر يې چې زمونږ ګواهى رښتينې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29538, '3 John 1:13', '3 John', 1, 13, '&nbsp;ما سره تاسو ته د ليکلو دپاره ډيرې خبرې دى خو دا نۀ غواړم چې په قلم او سياهۍ يې وليکم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29539, '3 John 1:14', '3 John', 1, 14, '&nbsp;زما اُميد دے چې ډېر زر به تاسو ووينم او مخامخ به د يو بل سره خبرې وکړُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29540, '3 John 1:15', '3 John', 1, 15, '&nbsp;په تا دې سلامتى وى. ستاسو ملګرى تاسو ته سلام وائى، هلته هر يو ملګرى ته په نامه سلام ووايه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29541, 'Jude 1:1', 'Jude', 1, 1, '&nbsp;دا خط د يهوداه د طرف نه دے چې د عيسىٰ مسيح غلام او د يعقوب ورور دے. زۀ هغوئ ته دا ليکم څوک چې رابللے شوى دى، چا سره چې خُدائ پلار مينه کوى او عيسىٰ مسيح دپاره يې محفوظ ساتى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29542, 'Jude 1:2', 'Jude', 1, 2, '&nbsp;رحم، سلامتيا او مينه دې په تاسو د حد نه زياته وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29543, 'Jude 1:3', 'Jude', 1, 3, '&nbsp;زما ګرانو دوستانو، اګر چې زما تاسو ته د هغه خلاصون په حقله د ليکلو ډېر زيات شوق وو په کوم کښې چې مونږ ټول شريک يُو، خو زۀ اوس تاسو ته د بل څيز په حقله ليکل غواړم او تاسو ته مِنت زارى کوم چې د هغه ايمان دفاع وکړئ کوم ايمان چې مقدسينو ته په يو ځل سپارلے شوے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29544, 'Jude 1:4', 'Jude', 1, 4, '&nbsp;ځکه چې څۀ خلق ستاسو په مينځ کښې راګډ شوى دى په چا چې د ډېر پخوا نه د مجرمانو مهر لګولے شوے دے، بې‌دينه خلق څوک چې زمونږ د خُدائ پاک فضل په عياشۍ بدلوى او زمونږ د يک يو مالِک، مالِک عيسىٰ مسيح نه اِنکار کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29545, 'Jude 1:5', 'Jude', 1, 5, '&nbsp;اګر کۀ تاسو ټول په دې ښۀ خبر يئ خو زۀ غواړم چې تاسو ته درياد کړم چې زمونږ مالِک څنګه بنى اِسرائيل د مِصر نه رابهر او بچ کړل، خو بيا وروستو يې هغه خلق تباه کړل چا چې ايمان نۀ وو راوړے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29546, 'Jude 1:6', 'Jude', 1, 6, '&nbsp;او هغه فرښتو چې خپل مقام يې ونۀ ساتلو او خپل ځائ يې پرېښودلو، نو خُدائ پاک هغوئ په ابدى زنځيرونو او په تورتم کښې د قيامت د لوئ ورځې پورې ساتلى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29547, 'Jude 1:7', 'Jude', 1, 7, '&nbsp;دغه شان د سدوم او عموره او د ګېرچاپېره ښارونو مِثال واخلئ چې د هغوئ خلق هم د غېر فطرى فعل او په زناکارۍ کښې پرېوتل، او هغوئ ته د عبرت په توګه په ابدى اور کښې سزا ورکولے کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29548, 'Jude 1:8', 'Jude', 1, 8, '&nbsp;نو په هم دې طريقه دا خلق د خپلو روياګانو په وجه خپل جسمونه پليتوى، د خُدائ پاک اختيار سپک ګڼى او جلالى مخلوق ته بدرد وائى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29549, 'Jude 1:9', 'Jude', 1, 9, '&nbsp;بلکې ياد ساتئ چې د ټولو نه لوئې فرښتې ميکائيل هم دغسې ونۀ کړل، ځکه چې څۀ وخت چې هغه د موسىٰ د لاش په باب د اِبليس سره بحث کولو په هغه وخت يې دومره همت ونۀ کړو چې په اِبليس اِلزام ولګوى، بلکې دا يې ووئيل چې، ”مالِک خُدائ دې تا ملامته کړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29550, 'Jude 1:10', 'Jude', 1, 10, '&nbsp;خو دا خلق هغه څيزونو ته بدرد وائى کوم چې دوئ نۀ پېژنى، او چې په کومو څيزونو دوئ په طبعى توګه لکه د بې‌شعوره ځناورو پوهيږى، نو په هم دې هغوئ خپل ځان تباه کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29551, 'Jude 1:11', 'Jude', 1, 11, '&nbsp;په هغوئ افسوس دے، ځکه چې هغوئ د قائِن لار خپله کړه، او هغوئ د ګټې دپاره بلعام په شان ګمراه شول، او هغوئ د قورح په شان مخالفت وکړو او د هغۀ په شان هلاک شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29552, 'Jude 1:12', 'Jude', 1, 12, '&nbsp;کله چې دا ګنده خلق ستاسو په مېلمستيا کښې تاسو سره په خوراک څښاک شراکت کوى نو هغوئ په ډېر بې‌ادبۍ سره خوراک کوى لکه د هغه شپونکو په شان چې صرف خپله ګېډه ډکوى. هغوئ د هغه بې‌بارانه وريځو په شان دى چې هوا په مخه کړې وى، او د منى د بې‌مېوې ونو په شان دى چې په دواړه اړخه مړې وى، يعنې د بېخه ويستلے شوې وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29553, 'Jude 1:13', 'Jude', 1, 13, '&nbsp;هغوئ د سمندر د طوفانى چپو په شان دى، خپل شرمناک عملونه لکه د ګنده ځګونو په شان راوچتوى، او لکه د هغه سرګردانه ستورو په شان دى چې د تل دپاره تورو تيارو ته لېږلے شوى دى او رڼا يې ختمه شوې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29554, 'Jude 1:14', 'Jude', 1, 14, '&nbsp;حنوک هم چې د آدم نه په اوومه پيړۍ کښې وو، د دوئ په باب کښې پېشګوئې وکړه او وئ فرمائيل چې، ”ګورئ، مالِک د خپلو زرګونو فرښتو سره راروان دے', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29555, 'Jude 1:15', 'Jude', 1, 15, '&nbsp;چې د ټولو عدالت وکړى او ټولو بې‌دينو له به د سزا حُکم ورکړى، ځکه چې هغوئ د خپلې بدعملى په وجه ډېر د بې‌دينۍ کارونه وکړل، او خُدائ پاک بې‌دينه ګناهګارانو له به هم د سزا ورکولو حُکم وکړى ځکه چې هغوئ د هغۀ خلاف ډېر بد وئيلى دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29556, 'Jude 1:16', 'Jude', 1, 16, '&nbsp;دا غورېدونکى او شکايت کوونکى خلق دى، هغوئ په خپلو خواهشاتو پسې روان دى، هغوئ د خپل ځان په حقله غټې غټې خبرې کوى او د خپل مقصد دپاره خلقو ته نرمې ګرمې خبرې کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29557, 'Jude 1:17', 'Jude', 1, 17, '&nbsp;خو زما ګرانو دوستانو، تاسو زمونږ د مالِک عيسىٰ مسيح د رسولانو پېشګويۍ يادې ساتئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29558, 'Jude 1:18', 'Jude', 1, 18, '&nbsp;هغوئ تاسو ته دا وئيلى وُو چې په آخره زمانه کښې به داسې خلق وى چې تاسو پورې به ټوقې کوى او د خپلې بې‌دينۍ په خواهشونو پسې به ګرځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29559, 'Jude 1:19', 'Jude', 1, 19, '&nbsp;دا هغه خلق دى چې ستاسو په مينځ کښې بيلتون راولى، هغوئ نفسانى دى او په کښې د خُدائ پاک روحُ نشته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29560, 'Jude 1:20', 'Jude', 1, 20, '&nbsp;خو زما ګرانو دوستانو، تاسو د خپل مقدس ايمان په بنياد يو بل قائم کړئ او د روحُ القُدس په طاقت دُعاګانې کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29561, 'Jude 1:21', 'Jude', 1, 21, '&nbsp;خپل ځانونه د خُدائ پاک په مينه کښې قائم وساتئ، او د هغې ورځې اِنتظار کوئ چې زمونږ مالِک عيسىٰ مسيح به تاسو ته په خپل رحم د تل ژوندون درکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29562, 'Jude 1:22', 'Jude', 1, 22, '&nbsp;په هغوئ رحم کوئ چې شک کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29563, 'Jude 1:23', 'Jude', 1, 23, '&nbsp;ځينې د اور لمبو نه راوچت کړئ او بچ يې کړئ، او په يرې سره په ځينې خلقو رحم کوئ، او د هغۀ د هغه ګناه نه نفرت کوئ په کوم چې هغه تور شوے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29564, 'Jude 1:24', 'Jude', 1, 24, '&nbsp;اوس هغه چې تاسو د غورزېدو نه بچ کولے شى او د خپل حضور په جلال کښې مو بغېر د ملامتيا نه په خوشحالۍ راوستے شى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29565, 'Jude 1:25', 'Jude', 1, 25, '&nbsp;د ايکې يو خُدائ پاک چې د مالِک عيسىٰ مسيح په وسيله زمونږ خلاصونکے دے، د هغۀ دې جلال، شان و شوکت، قُدرت او اختيار د ازل نه، اوس او تل تر تله وى. آمين.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29566, 'Revelation 1:1', 'Revelation', 1, 1, '&nbsp;دا هغه رويا ده چې خُدائ پاک عيسىٰ مسيح ته ورکړه چې هغه خپلو غلامانو ته هغه خبرې وښائى چې کومې به زر تر زره پېښيږى. هغۀ خپله فرښته خپل غلام يوحنا ته په رالېږلو دا خبرې هغۀ ته وښودلې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29567, 'Revelation 1:2', 'Revelation', 1, 2, '&nbsp;چا چې د خُدائ پاک د کلام او د عيسىٰ مسيح او د هغۀ ټول هر څۀ چې هغه وليدل ګواهى ورکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29568, 'Revelation 1:3', 'Revelation', 1, 3, '&nbsp;بختور دے هغه څوک چې دا پېشګوئى نورو خلقو ته لولى او بختور دى هغه خلق چې دا کلام اورى او چې څۀ په کښې ليکلى دى په هغې عمل کوى، ځکه چې وخت رانزدې دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29569, 'Revelation 1:4', 'Revelation', 1, 4, '&nbsp;دا خط د يوحنا د طرف نه د آسيه صوبې د اوو جماعتونو په نوم، په تاسو دې فضل او سلامتى وى، د خُدائ پاک د طرفه چې شته، چې وو او چې راتلونکے دے، او د هغه اوو روحونو د طرفه چې د هغۀ د تخت د وړاندې دى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29570, 'Revelation 1:5', 'Revelation', 1, 5, '&nbsp;او د عيسىٰ مسيح د طرف نه چې وفادار ګواه دے او چې د مړو نه اول ژوندے پاڅېدو او د زمکې د بادشاهانو سردار دے. هغه مونږ سره مينه کوى او مونږ يې د خپلې وينې په قربانۍ د ګناهونو نه آزاد کړُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29571, 'Revelation 1:6', 'Revelation', 1, 6, '&nbsp;هغۀ مونږ د خپل پلار خُدائ پاک د بادشاهت د خدمت دپاره اِمامان جوړ کړُو. د هغۀ جلالى قُدرت دې تل تر تله قائم وى. آمين.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29572, 'Revelation 1:7', 'Revelation', 1, 7, '&nbsp;ګورئ، هغه په وريځو کښې راروان دے، هره سترګه به هغه ووينى، او هغوئ هم چا چې هغه ژوبل کړے وو، او د دُنيا ټول خلق به په هغۀ وير کوى. بې‌شکه دا به دغه شان وى. آمين.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29573, 'Revelation 1:8', 'Revelation', 1, 8, '&nbsp;مالِک خُدائ پاک فرمائى چې، ”اول او آخر زۀ يم، چې شته، چې وو، چې راتلونکے دے يعنې قادر مطلق خُدائ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29574, 'Revelation 1:9', 'Revelation', 1, 9, '&nbsp;زۀ ستاسو ورور يوحنا، په تنګسيا، په بادشاهۍ او په صبر کښې تاسو سره خپل عيسىٰ کښې شريک يم. زۀ د خُدائ پاک د کلام او د عيسىٰ په حقله د ګواهۍ ورکولو په وجه پتموس نومې جزيره ته جلاوطن کړے شوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29575, 'Revelation 1:10', 'Revelation', 1, 10, '&nbsp;او د مالِک په ورځ چې روحُ القُدس په ما غلبه وکړه، نو ما خپل شا ته يو اوچت آواز واورېدو چې د بيګل په شان وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29576, 'Revelation 1:11', 'Revelation', 1, 11, '&nbsp;هغه آواز ما ته ووئيل چې، ”څۀ چې تۀ وينې هغه په يو کِتاب کښې وليکه او اوو واړو جماعتونو ته يې ولېږه، يعنې اِفِسوس، سمرنه، پرګمون، تواتيره، سرديس، فيلدِلفيه، او لوديکيه ته.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29577, 'Revelation 1:12', 'Revelation', 1, 12, '&nbsp;زۀ ورپسې راتاو شوم چې دا څوک دے چې ما سره خبرې کوى، او چې زۀ راتاو شوم نو ما د سرو زرو اووۀ ډيوټونه وليدل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29578, 'Revelation 1:13', 'Revelation', 1, 13, '&nbsp;او د دې ډيوټونو په مينځ کښې ما يو کس د اِبن آدم په شان وليدلو چې تر پښو پورې يې چُوغه اغوستې وه او په سينه يې د سرو زرو سينه بند تاو کړے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29579, 'Revelation 1:14', 'Revelation', 1, 14, '&nbsp;د هغۀ د سر وېښتۀ لکه د سپينې وړۍ او يا واورې په شان سپين وُو او د هغۀ سترګې د اور د شغلو په شان وې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29580, 'Revelation 1:15', 'Revelation', 1, 15, '&nbsp;او د هغۀ پښې د زېړو په شان ځلېدلې څنګه چې په بټۍ کښې سرې شوې وى او د هغۀ آواز لکه د تېزو اوبو په شان وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29581, 'Revelation 1:16', 'Revelation', 1, 16, '&nbsp;او هغۀ په ښى لاس کښې هغه اووۀ ستورى نيولى وُو او د هغۀ د خولې نه يوه تېزه دوه مخيزه تُوره راوتلې وه او د هغۀ مخ د تېز نمر په شان ځلېدو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29582, 'Revelation 1:17', 'Revelation', 1, 17, '&nbsp;کله چې هغه ما وليدو نو زۀ لکه د مړى د هغۀ په پښو کښې پرېوتلم، خو هغۀ خپل ښے لاس په ما کېښودو او وې فرمائيل، ”يرېږه مه، اول او آخر زۀ يم،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29583, 'Revelation 1:18', 'Revelation', 1, 18, '&nbsp;او ژوندے يم، زۀ مړ وم خو اوس تل تر تله ژوندے يم او د مرګ او د عالمِ ارواح کُنجيانې ما سره دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29584, 'Revelation 1:19', 'Revelation', 1, 19, '&nbsp;د دې دپاره دا هر څۀ وليکه څۀ چې تۀ وينې، څۀ چې اوس دى او څۀ چې وروستو به وشى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29585, 'Revelation 1:20', 'Revelation', 1, 20, '&nbsp;تا چې زما په ښى لاس کښې اووۀ ستورى ليدلى دى او هغه اووۀ د سرو زرو ډيوټونه، د هغې راز دا دے چې اووۀ ستورى د اوو جماعتونو فرښتې دى او دا اووۀ ډيوټونه اووۀ جماعتونه دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29586, 'Revelation 2:1', 'Revelation', 2, 1, '&nbsp;”د اِفِسوس د جماعت فرښتې ته دا پېغام وليکه، دا د هغۀ پېغام دے چا چې اووۀ ستورى په خپل ښى لاس کښې نيولى دى څوک چې د سرو زرو د اوو ډيوټونو په مينځ کښې ګرځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29587, 'Revelation 2:2', 'Revelation', 2, 2, '&nbsp;زۀ ستا د ټولو عملونو نه خبر يم. او ما ته ستا د خوارۍ او صبر هم پته ده. او ما ته د دې هم پته ده چې تۀ بدکاره خلق نۀ شې زغملے، تا هغوئ وآزمائيل څوک چې ځان ته رسولان وائى خو نۀ دى، او دروغژن دې ثابت کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29588, 'Revelation 2:3', 'Revelation', 2, 3, '&nbsp;ما ته دا هم پته ده چې زما د نوم د خاطره تا دا په صبر سره وزغمل او تۀ ستومانه نۀ شوې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29589, 'Revelation 2:4', 'Revelation', 2, 4, '&nbsp;خو زۀ ستا خلاف دا شکايت کوم چې تا هغه وړومبۍ مينه پرېښې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29590, 'Revelation 2:5', 'Revelation', 2, 5, '&nbsp;خو هغه راياد کړه چې تۀ د څومره اوچت مقام نه پرېوتلې، خو اوس توبه وباسه او هغه کار کوه لکه چې مخکښې دې کړے وو. کۀ تۀ توبه ونۀ باسې نو زۀ به راشم او ستا ډيوټ به د خپل ځائ نه لرې کړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29591, 'Revelation 2:6', 'Revelation', 2, 6, '&nbsp;خو بيا هم يوه خبره ستا په حق کښې شته چې تۀ د نيکليانو د کارونو نه نفرت کوې لکه چې زۀ يې ترې کوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29592, 'Revelation 2:7', 'Revelation', 2, 7, '&nbsp;د چا چې غوږونه وى، هغه دې واورى چې روحُ القُدس جماعتونو ته څۀ فرمائى. هر هغه څوک چې بريالے شى نو زۀ به د ژوندون د ونې نه د مېوې د خوړلو اختيار ورکړم چې د خُدائ پاک په جنت کښې ولاړه ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29593, 'Revelation 2:8', 'Revelation', 2, 8, '&nbsp;د سمرنه د جماعت فرښتې ته دا پېغام وليکه چې، څوک چې اول او آخر دے، او څوک چې مړ شو او بيا ژوندے شو، هغه داسې فرمائى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29594, 'Revelation 2:9', 'Revelation', 2, 9, '&nbsp;ما ته ستا د تنګسيا او غربت پته ده، خو بيا هم تۀ مالدار يې، زۀ د هغه خلقو د کُفر وئيلو نه هم خبر يم چې ځان ته يهوديان وائى خو دى نۀ. دا د شېطان جماعت دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29595, 'Revelation 2:10', 'Revelation', 2, 10, '&nbsp;د راتلونکو زحمتونو نه مۀ يرېږه. خبردار شئ اِبليس به تاسو نه ځينې قېدخانو ته واچوى نو چې تاسو وآزمائيلے شئ او تر لسو ورځو پورې به په تاسو زحمتونه وى. خو تر مرګه پورې وفادار اوسئ او زۀ به د ژوندون تاج در په سر کړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29596, 'Revelation 2:11', 'Revelation', 2, 11, '&nbsp;د چا چې غوږونه وى، هغه دې واورى، چې روحُ القُدس جماعتونو ته څۀ فرمائى. هر هغه څوک چې کامياب شى نو دوېم مرګ به ورته هيڅ نقصان ونۀ رسوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29597, 'Revelation 2:12', 'Revelation', 2, 12, '&nbsp;د پرګمون د جماعت فرښتې ته دا پېغام وليکه، هغه څوک چې چا سره تېرۀ دوه مخيزه تُوره ده هغه داسې فرمائى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29598, 'Revelation 2:13', 'Revelation', 2, 13, '&nbsp;ما ته پته ده چې تۀ چرته اوسې، هلته چرته چې د شېطان تخت دے او تۀ زما په نوم مضبوط ولاړ يې. تا په هغه وخت هم د خپل ايمان نه اِنکار ونۀ کړو کله چې زما وفادار ګواه انتيپاس ستاسو په هغه ښار کښې ووژلے شو چرته چې شېطان اوسيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29599, 'Revelation 2:14', 'Revelation', 2, 14, '&nbsp;خو زۀ ستا خلاف د يو څو خبرو شکايت کوم چې په تاسو کښې هلته څۀ کسان شته چې د بلعام د تعليم پيروى کوى، چا چې بلق ته تعليم ورکړو چې بنى اِسرائيل ګډ‌وډ کړى چې هغوئ بُتانو ته شوې قربانۍ وخورى او حرامکارى دې وکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29600, 'Revelation 2:15', 'Revelation', 2, 15, '&nbsp;هم دغه شان په تاسو کښې ځينې کسان شته دے چې د نيکليانو د تعليم پيروى کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');